import { Box, IconButton, ListItemSelect, Popover, Tag, TextButton } from '@wix/design-system';
import { Adjust } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import { RicosContext } from './../../../ricos-context/index.js';

export type WidgetType = {
  id: string;
  label: string;
  icon: React.ReactNode;
};

export const WidgetTypeSelector: React.FC<{
  options: WidgetType[];
  selectedId?: string;
  onSelect: (typeId: string) => void;
  onRemove: (typeId: string) => void;
}> = ({ selectedId, options, onSelect, onRemove }) => {
  const { t } = React.useContext(RicosContext);
  const [shown, setShown] = React.useState(false);
  const toggle = () => setShown(prev => !prev);

  return (
    <Box gap="8px" align="center" verticalAlign="middle">
      <Popover
        showArrow
        shown={shown}
        appendTo="scrollParent"
        placement="top"
        zIndex={5301}
        onClickOutside={() => setShown(false)}
      >
        <Popover.Element>
          <Box verticalAlign="middle">
            {selectedId ? (
              <Box marginInlineStart="-6px">
                <IconButton onClick={toggle} priority="tertiary" skin="dark">
                  <Adjust />
                </IconButton>
              </Box>
            ) : (
              <TextButton
                underline="onHover"
                prefixIcon={
                  <Box width="fit-content" height="100%" verticalAlign="middle">
                    <Adjust />
                  </Box>
                }
                onClick={toggle}
                skin="dark"
                size="medium"
              >
                {t('HtmlPlugin_AiWidget_WidgetTypeSelector_ButtonLabel')}
              </TextButton>
            )}
          </Box>
        </Popover.Element>
        <Popover.Content>
          <Box paddingBlock="12px" direction="vertical" maxWidth="200px">
            {options.map(option => (
              <ListItemSelect
                key={option.id}
                title={t(option.label)}
                prefix={option.icon}
                selected={selectedId === option.id}
                onClick={() => {
                  toggle();
                  onSelect(option.id);
                }}
                size="small"
              />
            ))}
          </Box>
        </Popover.Content>
      </Popover>
      {selectedId && (
        <Tag size="large" id={selectedId} removable onRemove={() => onRemove(selectedId)}>
          {t(options.find(option => option.id === selectedId)?.label ?? '')}
        </Tag>
      )}
    </Box>
  );
};
