import type { MiddlewareData, Placement, ReferenceType } from '@floating-ui/react-dom';
import { autoUpdate, flip, limitShift, offset, shift, useFloating } from '@floating-ui/react-dom';
import React, { useContext, useEffect, useState } from 'react';

import { RicosContext, ZIndexContext } from './../../ricos-context/index.js';
import type { ModalProps } from './../../ricos-types/index.js';
import { useToolbarBoundary } from './../../toolbars-v3/toolbar-boundary.js';
import { ClickOutside, UiComponentsProvider } from './../../ui-components/index.js';

import { FLOATING_CONTAINER_AI_WIDGET } from '../data-hooks.js';

export const FloatingContainer = ({
  children,
  modalConfig,
  onClickOutside,
}: {
  children: (args: { middlewareData: MiddlewareData; placement: Placement }) => React.ReactNode;
  modalConfig?: ModalProps['modalConfig'];
  onClickOutside: (e: PointerEvent) => void;
}) => {
  const { jsdomMode } = useContext(RicosContext);
  const zIndexService = useContext(ZIndexContext);
  const [modalElement, setModalElement] = useState<HTMLDivElement | null>(null);
  const referenceElement = modalConfig?.positioning?.referenceElement as HTMLElement;

  const boundary = useToolbarBoundary();

  const {
    x,
    y,
    refs: { setReference, setFloating },
    strategy,
    middlewareData,
    placement,
  } = useFloating({
    placement: modalConfig?.positioning?.placement as Placement,
    strategy: 'fixed',
    middleware: [
      offset({ mainAxis: 2 }),
      flip({
        boundary: boundary || undefined,
      }),
      shift({
        crossAxis: true,
        mainAxis: false,
        limiter: limitShift(),
        boundary: boundary || undefined,
      }),
    ],

    whileElementsMounted: (referenceEl, floatingEl, update) =>
      autoUpdate(referenceEl, floatingEl, update, {
        animationFrame: true,
      }),
  });

  useEffect(() => {
    setReference(referenceElement as ReferenceType);
  }, [setReference, referenceElement]);

  const isVisible = jsdomMode || Boolean(x || y);

  const escToClickOutside = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'Escape') {
      onClickOutside(e as $TSFixMe);
      return;
    }
  };

  return (
    <ClickOutside
      onClickOutside={onClickOutside}
      triggerOn={
        typeof modalConfig?.onClickOutside !== 'function'
          ? modalConfig?.onClickOutside?.on
          : undefined
      }
    >
      {/* oxlint-disable-next-line jsx-a11y/no-static-element-interactions */}
      <div
        ref={ref => {
          setFloating(ref);
          setModalElement(ref);
        }}
        onKeyDown={escToClickOutside}
        style={{
          width: referenceElement?.offsetWidth ? referenceElement.offsetWidth : 'auto',
          position: strategy,
          top: y ?? '',
          left: x ?? '',
          zIndex: zIndexService.getZIndex('DIALOG'),
          display: 'block',
          visibility: isVisible ? 'visible' : 'hidden',
        }}
        data-hook={FLOATING_CONTAINER_AI_WIDGET}
      >
        {modalElement && (
          <UiComponentsProvider containerEl={modalElement}>
            {children({ middlewareData, placement })}
          </UiComponentsProvider>
        )}
      </div>
    </ClickOutside>
  );
};
