import type { FunctionComponent } from 'react';
import React, { useCallback, useState } from 'react';

import { uuid } from './../wix-rich-content-common/index.js';

import { Iframe } from './iframe.js';

export const IframeUrl: FunctionComponent = props => {
  const [currId] = useState(() => uuid());
  const [isLoaded, setIsLoaded] = useState(false);

  const handleIframeLoad = useCallback(() => {
    setIsLoaded(true);
    // @ts-expect-error
    if (!window?.ricosHtmlPlugins) {
      // @ts-expect-error
      window.ricosHtmlPlugins = new Set();
    }
    // @ts-expect-error
    window.ricosHtmlPlugins.add(currId);
  }, [currId]);

  React.useEffect(() => {
    const timeout = setTimeout(() => {
      if (!isLoaded) {
        handleIframeLoad();
      }
    }, 5000);

    return () => clearTimeout(timeout);
  }, [isLoaded, handleIframeLoad]);

  return (
    <Iframe
      {...props}
      onLoad={handleIframeLoad}
      sandbox="allow-popups allow-presentation allow-forms allow-same-origin allow-scripts"
    />
  );
};
