import { generateId } from './../ricos-content/index.js';
import type { ModalService } from './../ricos-modals/index.js';
import { HTMLData_Source } from './../ricos-schema/next-schema/index.js';
import type { PublicCommands } from './../ricos-types/editor-commands-type.js';
import type { TiptapEditor } from './../ricos-types/tiptap.js';
import type { PmHtmlNode } from './../_shared/pm-node-types.js';

import { openFloatingPromptInput } from './tiptap/open-floating-prompt-input.js';
import { HTML_TYPE } from './types.js';

/** Shared by the AI widget quick action and `openModal({ type: 'AI_WIDGET' })`. */
export async function insertAiWidgetBlockAndOpenPrompt(options: {
  publicCommands: PublicCommands;
  editor: TiptapEditor;
  modals: ModalService;
  useWixelWidgets?: boolean;
  getColorPalette?: () => string[];
  canProceed?: () => Promise<boolean>;
}): Promise<void> {
  if (options.useWixelWidgets && options.canProceed) {
    const canProceed = await options.canProceed();
    if (!canProceed) {
      return;
    }
  }

  const nodeId = generateId();

  const attrs: Partial<PmHtmlNode['attrs']> = {
    id: nodeId,
    containerData: {
      alignment: 'CENTER',
      height: {
        custom: '474',
      },
      width: {
        custom: '900',
      },
    },
    source: options.useWixelWidgets ? HTMLData_Source.AI_WIDGET : HTMLData_Source.AI,
    state: {
      status: 'INITIAL',
    },
  };

  options.publicCommands.insertBlockWithBlankLines(HTML_TYPE, attrs, { updateSelection: false });

  openFloatingPromptInput({
    nodeId,
    editor: options.editor,
    modals: options.modals,
    getColorPalette: options.getColorPalette,
  });
}
