import { TIPTAP_HTML_TYPE } from './../../ricos-content/index.js';
import type { ExtensionProps, NodeConfig, RicosExtension } from './../../ricos-types/index.js';
import { createRicosNodeExtension } from './../../plugin-commons/index.js';

import { Html as Component } from './component.js';

export const tiptapExtensions = [
  createRicosNodeExtension({
    name: TIPTAP_HTML_TYPE,
    groups: ['not-overtypable'],
    type: 'react-node',
    reconfigure: (
      config: NodeConfig,
      _extensions: RicosExtension[],
      _props: ExtensionProps,
      settings: Record<string, unknown>
    ) => ({
      ...config,
      addOptions: () => settings,
    }),
    Component,
    createExtensionConfig() {
      return {
        name: this.name,
        atom: false,
        group:
          'block smartBlockCellContent layoutCellContent collapsibleListItemBodyContent tableCellContent',
        selectable: true,
        draggable: true,
        addAttributes: () => ({
          source: null,
          containerData: null,
          url: null,
          html: null,
          widgetId: null,
          isAdsense: null,
          autoHeight: { default: true },
          iframeHeight: null,
          loading: null,
          error: null,
          state: null,
        }),
      };
    },
  }),
];
