import { Box, SidePanel } from '@wix/design-system';
import type { FC } from 'react';
import React, { useContext, useRef, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { HTMLData_Source } from './../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { useBiNext } from './../../../_shared/bi-context-provider/bi-context-provider.js';
import { containsUrl } from './../../../_shared/link/contains-url.js';
import type { PmHtmlNode } from './../../../_shared/pm-node-types.js';
import { useNodeAttrs } from './../../../_shared/use-node-attrs.js';
import { HTML_EDIT_MODAL_ID } from './../../consts.js';
import { FooterActions, Panel, PanelHeader } from './../../../ui-components/index.js';

import { EDIT_PANEL, EDIT_PANEL_FOOTER_ACTIONS } from '../../data-hooks.js';
import type { AdsenseSourceInputProps } from './adsense-source-input.js';
import { AdsenseSourceInput } from './adsense-source-input.js';
import type { HtmlSourceInputProps } from './html-source-input.js';
import { HtmlSourceInput } from './html-source-input.js';

export type InsertModalProps = {
  nodeId: string;
  closeModal: () => void;
};

export const InsertModal: FC<InsertModalProps> = ({ nodeId, closeModal }) => {
  const { t } = useContext(RicosContext);
  const logBi = useBiNext({ pluginId: 'html', modalId: HTML_EDIT_MODAL_ID, nodeId });
  const { patchPmNodeAttrs, pmNodeAttrs } = useNodeAttrs(nodeId, 'HTML');

  const [htmlNodeAttrs, setHtmlNodeAttrs] = useState<Partial<PmHtmlNode['attrs']> | undefined>(
    pmNodeAttrs
  );

  const inputRef = useRef<HTMLInputElement | null>(null);

  const isAdsense = htmlNodeAttrs?.isAdsense ?? htmlNodeAttrs?.source === HTMLData_Source.ADSENSE;

  const HtmlComponent: React.FC<AdsenseSourceInputProps | HtmlSourceInputProps> = isAdsense
    ? AdsenseSourceInput
    : HtmlSourceInput;

  return (
    <div style={{ minHeight: 446 }}>
      <Panel closeButtonProps={{ onClick: closeModal }} dataHook={EDIT_PANEL}>
        <PanelHeader title={t('HtmlPlugin_Edit_Modal_Title')} />
        <Box direction="vertical" padding="SP3">
          <HtmlComponent
            htmlNodeAttrs={htmlNodeAttrs}
            onHtmlInputChange={(html: string) => {
              setHtmlNodeAttrs({ url: null, html });
            }}
            onLinkInputChange={(url: string) => {
              setHtmlNodeAttrs({ url: url ?? null, html: null });
            }}
            inputRef={inputRef}
          />
        </Box>
        <SidePanel.Footer showDivider>
          <FooterActions
            onCancel={closeModal}
            onSave={() => {
              if (htmlNodeAttrs?.url && !containsUrl(htmlNodeAttrs.url)) {
                inputRef.current?.focus();
                return;
              }

              htmlNodeAttrs && patchPmNodeAttrs?.(htmlNodeAttrs);

              closeModal();
            }}
            saveButtonLabel={t('HtmlEditPanel_Update')}
            dataHook={EDIT_PANEL_FOOTER_ACTIONS}
            logBi={logBi}
          />
        </SidePanel.Footer>
      </Panel>
    </div>
  );
};
