import { useRequestService } from './../../_shared/request-service-provider/request-service-provider.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';
import type { Node } from './../../tiptap/pm/model.js';
import { dataHook, uuid } from './../../wix-rich-content-common/index.js';
import { findNodeById } from './../../tiptap-editor/helpers/index.js';

import { AI_WIDGET_MODAL_ID_PREFIX } from '../consts.js';
import { AI_WIDGET_HTML_VIEWER, PROMPT_INPUT_AREA } from '../data-hooks.js';
import { htmlConverter } from '../html-converter.js';
import classes from './ai-widget-scss.js';
import { doPrompt } from './do-prompt.js';
import { ErrorIcon } from './error-icon.js';
import { FloatingContainer } from './floating-container.js';
import { Loader } from './loader.js';
import { openFloatingPromptInput } from './open-floating-prompt-input.js';
import type { Preset } from './preset-bar/preset-bar.js';
import { FIX_BUTTON_PRESET, PresetBar, PresetList } from './preset-bar/preset-bar.js';
import { useHandleFileUpload } from './use-handle-file-upload.js';

const FIX_WIDGET_PROMPT = 'Widget is broken. Analyze the HTML, find issues and fix them.' as const;

export const getModalId = (nodeId: string) => `${AI_WIDGET_MODAL_ID_PREFIX}${nodeId}`;

export const AiWidget: React.FC<{
  htmlNode: Node;
  children: React.ReactNode;
  isFloatingPromptOpen: boolean;
  getColorPalette?: () => string[];
  htmlAiGeneration?: {
    canProceed?: () => Promise<boolean>;
    onRequestFailed?: (info: { status: number; response: Response }) => void;
  };
}> = props => {
  const { htmlNode, children, isFloatingPromptOpen, getColorPalette, htmlAiGeneration } = props;
  const zIndexService = React.useContext(ZIndexContext);
  const { patchPmNodeAttrs, pmNodeAttrs } = useNodeAttrs(htmlNode.attrs.id, 'HTML');
  const { makeRequest } = useRequestService();
  const {
    adapter: { tiptapEditor: editor },
    getPublicCommands,
  } = React.useContext(EditorContext);
  const modals = useModalService();
  const [aiWidgetContainerRef, setAiWidgetContainerRef] = useState<HTMLDivElement | null>(null);
  const selection = useSelection();

  useEffect(() => {
    const isWidgetSelected = isOnlyNodeSelected(editor.state, htmlNode.attrs.id);

    const nodeId = htmlNode.attrs.id;
    if (!modals.isModalOpen(getModalId(nodeId)) && isWidgetSelected) {
      modals.openModal({
        id: getModalId(nodeId),
        Component: FloatingPromptInput,
        componentProps: {
          nodeId,
          onSubmit: handleSubmit,
          getColorPalette,
        },
        type: 'exclusive',
        layout: 'manual',
        positioning: {
          referenceElement: aiWidgetContainerRef,
          placement: 'top',
        },
      });
      return;
    }

    if (modals.isModalOpen(getModalId(nodeId)) && !isWidgetSelected) {
      modals.closeModal(getModalId(nodeId));
    }

    return () => {
      if (modals.isModalOpen(getModalId(nodeId))) {
        modals.closeModal(getModalId(nodeId));
      }
    };
  }, [selection, modals]);

  const handleSubmit = React.useCallback(
    async ({ text, attachments }: { text: string; attachments: Attachment[] }) => {
      const currentRequestId = uuid();

      const isAiWidget = pmNodeAttrs?.source === HTMLData_Source.AI_WIDGET;

      if (isAiWidget && htmlAiGeneration?.canProceed) {
        const canProceed = await htmlAiGeneration.canProceed();
        if (!canProceed) {
          return;
        }
      }

      // Store the state before LOADING so we can restore it when setting SUCCESS
      const stateBeforeLoading = { ...pmNodeAttrs };

      editor.commands.closeHistory();

      patchPmNodeAttrs?.(
        {
          state: {
            status: 'LOADING',
            requestId: currentRequestId,
            prompt: { text, fileRefs: attachments },
          },
        },
        { skipHistory: true }
      );

      // Get fresh document and node state at submission time, not render time
      const currentDocument = getPublicCommands().getContent() as unknown as RicosDocument;
      const ricosNode = htmlConverter.fromPm.convert(htmlNode.toJSON()) as HtmlNode;

      const widgetPos = findNodeById(editor.view.state.tr, htmlNode.attrs.id)?.[0]?.pos;
      const documentContext =
        isAiWidget && widgetPos !== undefined
          ? editor.state.doc.textBetween(0, widgetPos, '\n\n', '\n\n').trim() || undefined
          : undefined;

      const response = await doPrompt({
        documentContext,
        prompt: text,
        document: currentDocument,
        selection: ricosNode ? [ricosNode] : [],
        files: attachments
          .filter(file => file.status === 'ok')
          .map(file => ({
            fileId: file.file.url,
            name: file.file.name,
          })),
        makeRequest,
        widgetType: undefined,
        outputMode: isAiWidget ? ('WIDGET' as OutputMode) : undefined,
        colorPalette: isAiWidget ? getColorPalette?.() : undefined,
        onRequestFailed: isAiWidget ? htmlAiGeneration?.onRequestFailed : undefined,
      });

      const tr = editor.view.state.tr;
      const nodeWithPos = findNodeById(tr, pmNodeAttrs?.id ?? '');
      const { node } = (nodeWithPos?.[0] ?? {}) as unknown as { node: PmHtmlNode };

      if (
        response.type === 'SUCCESS' &&
        node?.attrs?.state?.status === 'LOADING' &&
        node?.attrs?.state?.requestId === currentRequestId
      ) {
        // First restore INITIAL state (skip history), then set SUCCESS (add to history)
        // This ensures undo goes back to INITIAL, not LOADING
        patchPmNodeAttrs?.(
          {
            ...stateBeforeLoading,
          },
          { skipHistory: true }
        );

        if ('widgetId' in response) {
          patchPmNodeAttrs?.({
            widgetId: response.widgetId,
            containerData: response.containerData,
            state: { status: 'SUCCESS' },
          });
        } else if ('html' in response) {
          patchPmNodeAttrs?.({
            html: response.html,
            containerData: response.containerData,
            state: { status: 'SUCCESS' },
          });
        }
      }

      if (
        response.type === 'ERROR' &&
        node?.attrs?.state?.status === 'LOADING' &&
        node?.attrs?.state?.requestId === currentRequestId
      ) {
        // First restore INITIAL state (skip history), then set ERROR (add to history)
        // This ensures undo goes back to INITIAL, not LOADING
        patchPmNodeAttrs?.(
          {
            ...stateBeforeLoading,
          },
          { skipHistory: true }
        );

        patchPmNodeAttrs?.({
          state: {
            status: 'ERROR',
            error: response.error,
            prompt: node?.attrs?.state?.prompt,
          },
        });
      }
    },
    [
      patchPmNodeAttrs,
      pmNodeAttrs?.state,
      pmNodeAttrs?.source,
      makeRequest,
      htmlNode,
      getPublicCommands,
      htmlAiGeneration,
    ]
  );

  const handleCancel = React.useCallback(() => {
    patchPmNodeAttrs?.({ state: { status: 'SUCCESS', prompt: pmNodeAttrs?.state?.prompt } });
  }, [patchPmNodeAttrs, pmNodeAttrs?.state?.prompt]);

  if (!pmNodeAttrs) {
    logInvariant(new Error('AI Widget: pmNodeAttrs is undefined'));
    return null;
  }

  const hasContent = pmNodeAttrs.html || pmNodeAttrs.widgetId;

  if (!hasContent) {
    if (pmNodeAttrs.state?.status === 'ERROR') {
      return (
        <ErrorDisplay
          onRetry={() => {
            handleSubmit({
              text: pmNodeAttrs?.state?.prompt?.text ?? '',
              attachments: pmNodeAttrs?.state?.prompt?.fileRefs ?? [],
            });
          }}
          onNewPrompt={() => {
            patchPmNodeAttrs({
              state: {
                status: 'INITIAL',
              },
            });
            openFloatingPromptInput({
              nodeId: pmNodeAttrs.id,
              editor,
              modals,
            });
          }}
        />
      );
    }

    if (pmNodeAttrs.state?.status === 'LOADING') {
      return (
        <LoadingDisplay
          onStop={() => {
            patchPmNodeAttrs({ state: { status: 'INITIAL', prompt: pmNodeAttrs?.state?.prompt } });

            openFloatingPromptInput({
              nodeId: pmNodeAttrs.id,
              editor,
              modals,
            });
          }}
        />
      );
    }

    logInvariant(new Error('AI Widget: pmNodeAttrs.html is undefined'));

    return null;
  }

  return (
    // eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions
    <div
      className={isFloatingPromptOpen ? classes.wrapper : undefined}
      style={{
        width: '100%',
        zIndex: isFloatingPromptOpen ? (zIndexService.getZIndex('TOOLBAR') as number) - 1 : 1,
      }}
      onClick={() => {
        const nodeId = pmNodeAttrs.id;
        if (!modals.isModalOpen(getModalId(nodeId))) {
          modals.openModal({
            id: getModalId(nodeId),
            Component: FloatingPromptInput,
            componentProps: {
              nodeId,
              onSubmit: handleSubmit,
              getColorPalette,
            },
            type: 'exclusive',
            layout: 'manual',
            positioning: {
              referenceElement: aiWidgetContainerRef,
              placement: 'top',
            },
          });
          return;
        }
      }}
    >
      <div
        data-hook={AI_WIDGET_HTML_VIEWER}
        data-node-id={pmNodeAttrs.id}
        ref={setAiWidgetContainerRef}
        className={getPluginFocusClassNames(isFloatingPromptOpen)}
      >
        {pmNodeAttrs.state?.status === 'LOADING' ? (
          <LoadingDisplay onStop={handleCancel} isIterating />
        ) : pmNodeAttrs.state?.status === 'ERROR' ? (
          <ErrorDisplay
            onRetry={() => {
              handleSubmit({
                text: pmNodeAttrs.state?.prompt?.text ?? '',
                attachments: pmNodeAttrs?.state?.prompt?.fileRefs ?? [],
              });
            }}
          />
        ) : (
          <>{children}</>
        )}
      </div>
    </div>
  );
};

const FloatingPromptInput: React.FC<{
  nodeId: string;
  onSubmit: (args: { text: string; attachments: Attachment[]; shouldFixWidget?: boolean }) => void;
  getColorPalette?: () => string[];
}> = props => {
  const { onSubmit, nodeId } = props;
  const { t, lastInteraction } = useContext(RicosContext);
  const promptInputAreaRef = useRef<PromptInputAreaRef>(null);
  const modals = useModalService();
  const handleFileUpload = useHandleFileUpload();
  const { patchPmNodeAttrs, pmNodeAttrs } = useNodeAttrs(nodeId, 'HTML');
  const [promptText, setPromptText] = React.useState<string>(
    pmNodeAttrs?.state?.prompt?.text ?? ''
  );

  useEffect(() => {
    if (lastInteraction === 'mouse' && promptInputAreaRef.current) {
      promptInputAreaRef.current.focus();
    }
  }, [lastInteraction, promptInputAreaRef.current]);

  const handleCancel = React.useCallback(() => {
    if (!pmNodeAttrs) {
      return;
    }

    patchPmNodeAttrs({ state: { status: 'SUCCESS', prompt: pmNodeAttrs?.state?.prompt } });
  }, [patchPmNodeAttrs, pmNodeAttrs?.state?.prompt]);

  const handleClickOutside = React.useCallback(
    (e?: PointerEvent) => {
      if (!pmNodeAttrs) {
        return;
      }

      const target = e?.target as HTMLElement | undefined;
      const aiWidgetElement = target?.closest(dataHook(AI_WIDGET_HTML_VIEWER));

      if (e && aiWidgetElement?.getAttribute('data-node-id') === pmNodeAttrs.id) {
        return;
      }

      modals.closeModal(getModalId(pmNodeAttrs.id));
    },
    [modals, pmNodeAttrs?.id]
  );

  if (!pmNodeAttrs) {
    return null;
  }

  const isAiWidget = pmNodeAttrs.source === HTMLData_Source.AI_WIDGET;
  const SelectedPromptInputArea = isAiWidget ? WidgetPromptInputArea : PromptInputArea;

  return (
    <FloatingContainer {...props} onClickOutside={handleClickOutside}>
      {({ middlewareData, placement }) => (
        <SelectedPromptInputArea
          placeholder={t('HtmlPlugin_AiWidget_Input_Placeholder_Text')}
          ref={promptInputAreaRef}
          maxLength={10000}
          zIndex={1000}
          forceMultiline
          dataHook={PROMPT_INPUT_AREA}
          readonly={pmNodeAttrs.state?.status === 'LOADING'}
          busy={pmNodeAttrs.state?.status === 'LOADING'}
          busyValue={
            pmNodeAttrs.state?.prompt?.text === FIX_WIDGET_PROMPT
              ? ''
              : (pmNodeAttrs.state?.prompt?.text ?? '')
          }
          value={promptText}
          attachments={
            pmNodeAttrs.state?.status === 'SUCCESS' || pmNodeAttrs.state?.status === 'LOADING'
              ? (pmNodeAttrs?.state?.prompt?.fileRefs ?? [])
              : []
          }
          onChange={text => {
            setPromptText(text);
          }}
          onSubmit={() => {
            setPromptText('');
            onSubmit({ text: promptText, attachments: pmNodeAttrs?.state?.prompt?.fileRefs ?? [] });
          }}
          onCancel={handleCancel}
          onClose={handleClickOutside}
          minHeight={isAiWidget ? '36px' : '60px'}
          style={
            middlewareData.shift?.y
              ? {
                  borderRadius: 0,
                  borderBottom: '1px solid rgba(0, 6, 36, 0.1)',
                  boxShadow: '0 0 8px 0 rgba(0, 6, 36, 0.1), 0 6px 6px 0 rgba(0, 6, 36, 0.05)',
                }
              : placement === 'top'
                ? {
                    borderBottomRightRadius: 0,
                    borderBottomLeftRadius: 0,
                    borderBottom: 'none',
                  }
                : {
                    borderTopRightRadius: 0,
                    borderTopLeftRadius: 0,
                    borderTop: 'none',
                  }
          }
          className={classes.promptInputArea}
          hasSelectedNode
          fileUploadFn={async () => {
            await handleFileUpload(nodeId);
          }}
          onRemoveAttachment={id => {
            patchPmNodeAttrs({
              // @ts-expect-error
              state: {
                ...pmNodeAttrs?.state,
                prompt: {
                  text: pmNodeAttrs?.state?.prompt?.text ?? '',
                  fileRefs:
                    pmNodeAttrs?.state?.prompt?.fileRefs?.filter(file => file.id !== id) ?? [],
                },
              },
            });
          }}
          presetBarComponent={
            isAiWidget ? (
              <PresetList
                presets={PRESETS}
                onPresetSelect={preset => {
                  if (pmNodeAttrs.state?.status === 'LOADING') {
                    return;
                  }

                  setPromptText(preset.prompt ?? '');
                }}
              />
            ) : (
              <PresetBar
                presets={PRESETS}
                onPresetSelect={preset => {
                  if (pmNodeAttrs.state?.status === 'LOADING') {
                    return;
                  }

                  if (preset.id === FIX_BUTTON_PRESET.id) {
                    setPromptText('');
                    onSubmit({
                      text: FIX_WIDGET_PROMPT,
                      attachments: pmNodeAttrs?.state?.prompt?.fileRefs ?? [],
                      shouldFixWidget: true,
                    });
                    return;
                  }

                  setPromptText(preset.prompt ?? '');
                }}
                showFixButton
              />
            )
          }
        />
      )}
    </FloatingContainer>
  );
};

const ErrorDisplay: React.FC<{
  onRetry: () => void;
  onNewPrompt?: () => void;
}> = ({ onRetry, onNewPrompt }) => {
  const { t } = useContext(RicosContext);
  return (
    <>
      <Box padding="48px" direction="vertical" align="center" height="100%" width="100%">
        <ErrorIcon />
        <Box
          direction="vertical"
          width="100%"
          align="center"
          gap="4px"
          marginTop="30px"
          marginBottom="24px"
        >
          <Heading size="large">{t('HtmlPlugin_AiWidget_Error_Message_Title')}</Heading>
          <Text size="small" weight="thin">
            {t('HtmlPlugin_AiWidget_Error_Message_Subtitle')}
          </Text>
        </Box>
        <Box gap="24px" align="center" verticalAlign="middle">
          {onNewPrompt && (
            <TextButton prefixIcon={<SparklesFilled />} onClick={onNewPrompt}>
              {t('HtmlPlugin_AiWidget_Error_NewPromptButton')}
            </TextButton>
          )}
          <Button
            priority="secondary"
            skin="ai"
            prefixIcon={<RegenerateSparkle />}
            onClick={onRetry}
          >
            {t('HtmlPlugin_AiWidget_Error_RetryButton')}
          </Button>
        </Box>
      </Box>
    </>
  );
};

const LoadingDisplay: React.FC<{
  onStop: () => void;
  isIterating?: boolean;
}> = ({ onStop, isIterating }) => {
  const { t } = useContext(RicosContext);
  return (
    <Box padding="48px" direction="vertical" align="center" height="100%" width="100%">
      <Loader />
      <Box
        direction="vertical"
        width="100%"
        align="center"
        gap="4px"
        marginTop="30px"
        marginBottom="24px"
      >
        <Heading size="large">
          {isIterating
            ? t('HtmlPlugin_AiWidget_Loading_Iterating_Title')
            : t('HtmlPlugin_AiWidget_Loading_Building_Title')}
        </Heading>
        <Text size="small" weight="thin">
          {isIterating
            ? t('HtmlPlugin_AiWidget_Loading_Iterating_Subtitle')
            : t('HtmlPlugin_AiWidget_Loading_Building_Subtitle')}
        </Text>
      </Box>
      {!isIterating && (
        <Button priority="secondary" prefixIcon={<StopFilled />} onClick={onStop}>
          {t('HtmlPlugin_AiWidget_StopButton')}
        </Button>
      )}
    </Box>
  );
};

