import { Edit, Height, Width } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import { TIPTAP_HTML_TYPE } from './../ricos-content/index.js';
import { HTMLData_Source } from './../ricos-schema/next-schema/index.js';
import type { Resolver, RicosServices, ToolbarButton } from './../ricos-types/index.js';
import { createAnimationButton } from './../_shared/plugin-toolbar/create-animation-button.js';
import { createDeleteButton } from './../_shared/plugin-toolbar/create-delete-button.js';
import { createNodeAlignmentButton } from './../_shared/plugin-toolbar/create-node-alignment-button.js';
import { createSeparator } from './../_shared/plugin-toolbar/separator/create-separator.js';
import type { PmHtmlNode } from './../_shared/pm-node-types.js';
import { getNodeInSelection } from './../_shared/resolvers/get-node-in-selection.js';
import { FLOATING_PLUGIN_TOOLBAR } from './../toolbars-v3/index.js';

import { HTML_BUTTONS, HTML_EDIT_MODAL_ID } from './consts.js';
import {
  PLUGIN_TOOLBAR_CONTAINER_HEIGHT_BUTTON,
  PLUGIN_TOOLBAR_CONTAINER_WIDTH_BUTTON,
  PLUGIN_TOOLBAR_EDIT_HTML_BUTTON,
} from './data-hooks.js';
import { MAX_HEIGHT, MAX_WIDTH, MIN_HEIGHT, MIN_WIDTH } from './defaults.js';
import { DimensionSliderButton } from './toolbar/dimension-slider-button.js';
import { EditHtmlButton } from './toolbar/edit-html-button.js';
import { InsertModal } from './toolbar/insert-modal/insert-modal.js';
import type { SliderModalProps } from './toolbar/slider-modal.js';
import { SliderModal } from './toolbar/slider-modal.js';
import type { HtmlPluginEditorConfig } from './types.js';

export const getToolbarButtons = (
  config: HtmlPluginEditorConfig,
  services: RicosServices
): ToolbarButton[] => {
  const {
    minHeight = MIN_HEIGHT,
    maxHeight = MAX_HEIGHT,
    maxWidth = MAX_WIDTH,
    minWidth = MIN_WIDTH,
  } = config || {};

  const {
    modals,
    context: { isMobile },
  } = services;

  const editButton: ToolbarButton = {
    id: HTML_BUTTONS.edit,
    type: 'modal',
    dataHook: PLUGIN_TOOLBAR_EDIT_HTML_BUTTON,
    icon: Edit,
    renderer: toolbarItem => <EditHtmlButton id={HTML_EDIT_MODAL_ID} toolbarItem={toolbarItem} />,
    tooltip: 'HtmlPlugin_EditHtml_Tooltip',
    attributes: {
      selectedNode: getNodeInSelection,
      active: (_, { modals }) => Boolean(modals?.getModal(HTML_EDIT_MODAL_ID)),
      visible: isEditableHtmlResolver,
    },
    command: ({ attributes, modals, referenceElement }) => {
      const isModalOpen = modals.isModalOpen(HTML_EDIT_MODAL_ID);
      isModalOpen
        ? modals.closeModal(HTML_EDIT_MODAL_ID)
        : modals.openModal({
            Component: InsertModal,
            id: HTML_EDIT_MODAL_ID,
            componentProps: {
              nodeId: attributes.selectedNode.attrs.id,
              closeModal: () => modals.closeModal(HTML_EDIT_MODAL_ID),
            },
            layout: isMobile ? 'fullscreen' : 'floating',
            positioning: {
              referenceElement:
                referenceElement?.closest(`[data-hook~=${FLOATING_PLUGIN_TOOLBAR}]`) ??
                referenceElement,
              placement: 'right-start',
            },
            withTransition: true,
            noPadding: true,
            type: 'exclusive',
            enableDrag: !isMobile,
            dragHandleSelector: '[data-drag-handler]',
            returnFocusToEditor: true,
            focusReturnElement: referenceElement ?? undefined,
            onClickOutside: {
              on: 'pointerup',
              handler: e => {
                if (!referenceElement?.contains?.(e.target as Node)) {
                  modals.closeModal(HTML_EDIT_MODAL_ID);
                  return;
                }
              },
            },
          });
    },
  };
  const separator1 = createSeparator({
    visible: isEditableHtmlResolver,
  });
  const widthButton: ToolbarButton = {
    id: HTML_BUTTONS.width,
    type: 'modal',
    command: ({ tiptapEditor, referenceElement, attributes: { selectedNode } }) => {
      const { attrs } = selectedNode as PmHtmlNode;
      const onChange = ({ value }: { value: number; autoHeight?: boolean }) => {
        const changedData = {
          ...attrs,
          containerData: {
            ...attrs.containerData,
            width: {
              custom: value,
            },
          },
        };
        // to avoid flushSync error
        setTimeout(() => {
          tiptapEditor.chain().updateAttributes(TIPTAP_HTML_TYPE, changedData).run();
        }, 0);
      };

      const componentProps: SliderModalProps = {
        onChange,
        closeModal: () => modals.closeModal(HTML_BUTTONS.width),
        min: minWidth,
        max: maxWidth,
        dimension: 'width',
        nodeId: selectedNode.attrs.id,
      };

      modals.togglePluginPanel({
        isMobile,
        id: HTML_BUTTONS.width,
        Component: SliderModal,
        componentProps,
        positioning: {
          referenceElement:
            referenceElement?.closest(`[data-hook~=${FLOATING_PLUGIN_TOOLBAR}]`) ??
            referenceElement,
          placement: isMobile ? 'bottom' : 'right-start',
        },
        focusReturnElement: referenceElement,
        mobileLayout: 'drawer',
      });
    },
    icon: Width,
    tooltip: 'ChangeDimensions_Width_Tooltip',
    dataHook: PLUGIN_TOOLBAR_CONTAINER_WIDTH_BUTTON,
    renderer: toolbarItem => <DimensionSliderButton toolbarItem={toolbarItem} dimension="width" />,
    attributes: {
      selectedNode: getNodeInSelection,
      active: (_, { modals }) => Boolean(modals?.getModal(HTML_BUTTONS.width)),
    },
  };
  const heightButton: ToolbarButton = {
    id: HTML_BUTTONS.height,
    type: 'modal',
    command: ({ tiptapEditor, referenceElement, attributes: { selectedNode } }) => {
      const { attrs } = selectedNode as PmHtmlNode;
      const onChange = ({ value, autoHeight }: { value: number; autoHeight?: boolean }) => {
        const changedData = {
          ...attrs,
          containerData: {
            ...attrs.containerData,
            height: {
              custom: value,
            },
          },
          autoHeight,
        };

        // to avoid flushSync error
        setTimeout(() => {
          tiptapEditor.chain().updateAttributes(TIPTAP_HTML_TYPE, changedData).run();
        }, 0);
      };

      const componentProps: SliderModalProps = {
        onChange,
        closeModal: () => modals.closeModal(HTML_BUTTONS.height),
        min: minHeight,
        max: maxHeight,
        dimension: 'height',
        nodeId: selectedNode.attrs.id,
      };

      modals.togglePluginPanel({
        isMobile,
        id: HTML_BUTTONS.height,
        Component: SliderModal,
        componentProps,
        positioning: {
          referenceElement:
            referenceElement?.closest(`[data-hook~=${FLOATING_PLUGIN_TOOLBAR}]`) ??
            referenceElement,
          placement: isMobile ? 'bottom' : 'right-start',
        },
        focusReturnElement: referenceElement,
        mobileLayout: 'drawer',
      });
    },
    icon: Height,
    tooltip: 'ChangeDimensions_Height_Tooltip',
    dataHook: PLUGIN_TOOLBAR_CONTAINER_HEIGHT_BUTTON,
    renderer: toolbarItem => <DimensionSliderButton toolbarItem={toolbarItem} dimension="height" />,
    attributes: {
      selectedNode: getNodeInSelection,
      active: (_, { modals }) => Boolean(modals?.getModal(HTML_BUTTONS.height)),
    },
  };
  const alignmentButton = createNodeAlignmentButton({
    services,
    modalId: HTML_BUTTONS.alignment,
    attributes: {
      visible: (content: $TSFixMe) => {
        if (isMobile) {
          return false;
        }

        if (Array.isArray(content) && content.length > 0) {
          const source = content.find(node => node.type.name === TIPTAP_HTML_TYPE)?.attrs?.source;
          return source !== HTMLData_Source.AI && source !== HTMLData_Source.AI_WIDGET;
        }
        return false;
      },
    },
  });
  const separator2 = createSeparator();
  const animation = createAnimationButton(services);
  const deleteButton = createDeleteButton();

  if (services.context.environment === 'wixel') {
    return [editButton, widthButton, heightButton, alignmentButton, animation, deleteButton];
  }

  return [
    editButton,
    separator1,
    widthButton,
    heightButton,
    alignmentButton,
    animation,
    separator2,
    deleteButton,
  ];
};

const isEditableHtmlResolver: Resolver<boolean> = content => {
  if (Array.isArray(content) && content.length > 0) {
    const source = content.find(node => node.type.name === TIPTAP_HTML_TYPE)?.attrs?.source;
    return source !== HTMLData_Source.AI && source !== HTMLData_Source.AI_WIDGET;
  }
  return false;
};
