import { GoogleAds, PageCode } from '@wix/wix-ui-icons-common/lazy';

import { HTMLData_Source } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import htmlDataDefaults from './../ricos-schema/legacy/statics/html.defaults.json.js';
import type { AddButton, RicosServices } from './../ricos-types/index.js';
import { Node_Type } from './../ricos-types/index.js';
import { INSERT_PLUGIN_BUTTONS, TOOLBARS } from './../editor-common/index.js';

import { INSERT_ADSENSE_BUTTON, INSERT_HTML_BUTTON } from './data-hooks.js';
import { htmlButtonsTypes } from './defaults.js';
import type { HtmlPluginEditorConfig } from './types.js';
import { HTML_TYPE } from './types.js';

export const toolbarsToAddIn: (TOOLBARS.MOBILE | TOOLBARS.FOOTER | TOOLBARS.SIDE)[] = [
  TOOLBARS.MOBILE,
  TOOLBARS.FOOTER,
  TOOLBARS.SIDE,
];

export const getAddButtons = (
  config: HtmlPluginEditorConfig,
  _services: RicosServices
): AddButton[] => {
  const { exposeButtons = [htmlButtonsTypes.html], siteDomain } = config || {};
  const index = exposeButtons.indexOf(htmlButtonsTypes.adsense);
  if (!siteDomain && index > -1) {
    exposeButtons.splice(index, 1);
  }
  const buttonsMap: Record<string, AddButton> = {
    [htmlButtonsTypes.html]: {
      id: `${Node_Type.HTML}.html`,
      label: INSERT_PLUGIN_BUTTONS.HTML,
      dataHook: INSERT_HTML_BUTTON,
      icon: PageCode,
      tooltip: 'HtmlPlugin_InsertButton_Tooltip',
      toolbars: toolbarsToAddIn,
      command: ({ publicCommands }) => {
        publicCommands.insertBlockWithBlankLines(HTML_TYPE, {
          ...htmlDataDefaults,
          state: {
            status: 'SUCCESS',
          },
        });
        return true;
      },
      menuConfig: {
        tags: 'Video_plugin_search_tags',
      },
    },
    [htmlButtonsTypes.adsense]: {
      id: `${Node_Type.HTML}.adsense`,
      label: INSERT_PLUGIN_BUTTONS.ADSENSE,
      dataHook: INSERT_ADSENSE_BUTTON,
      icon: GoogleAds,
      tooltip: 'AdSensePlugin_InsertButton_Tooltip',
      toolbars: toolbarsToAddIn,
      command: ({ publicCommands }) => {
        publicCommands.insertBlockWithBlankLines(HTML_TYPE, {
          ...htmlDataDefaults,
          source: HTMLData_Source.ADSENSE,
          state: {
            status: 'SUCCESS',
          },
        });
        return true;
      },
      menuConfig: {
        tags: 'Video_plugin_search_tags',
        group: 'embed',
      },
    },
  };

  return exposeButtons.map(buttonType => buttonsMap[buttonType]).filter(x => !!x);
};
