import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../ricos-modals/modal-service-provider.js';
import type { IToolbarItem } from './../../ricos-types/index.js';
import { ToolbarButton } from './../../_shared/toolbar-button/toolbar-button.js';

import { HTML_BUTTONS } from '../consts.js';

interface Props {
  toolbarItem: IToolbarItem;
  dimension: 'width' | 'height';
  dataHook?: string;
}

export const DimensionSliderButton: FC<Props> = ({ toolbarItem, dataHook, dimension }) => {
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);
  const { t, isMobile } = useContext(RicosContext) || {};
  const isModalOpen = useModalState(getIsModalOpen(HTML_BUTTONS[dimension]));

  const { icon, tooltip } = toolbarItem.presentation;

  const onClick = () => {
    toolbarItem.commands?.click({ referenceElement, isMobile });
  };

  return (
    <ToolbarButton
      ref={setReferenceElement}
      active={isModalOpen}
      prefix={icon}
      onClick={onClick}
      dataHook={dataHook}
      tooltip={t(tooltip)}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
