import React, { useCallback, useEffect, useMemo, useState } from 'react';

import { useModalService } from './../../ricos-modals/index.js';
import type { HTMLData, HtmlNode } from './../../ricos-schema/next-schema/index.js';
import { HTMLData_Source } from './../../ricos-schema/next-schema/index.js';
import type { PluginProps } from './../../ricos-types/index.js';
import { DraggableHOC } from './../../_shared/draggable-hoc.js';
import { logInvariant } from './../../_shared/log-invariant.js';
import { OverlayHoc } from './../../_shared/overlay-hoc/overlay-hoc.js';
import { useWixInstanceService } from './../../_shared/request-service-provider/wix-instance-context.js';
import { useEditorProp } from './../../_shared/some-editor-props-context.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';

import { htmlConverter } from '../html-converter.js';
import { HtmlViewer as HtmlViewerComponent } from '../viewer/html-viewer.js';
import { AiWidget, getModalId } from './ai-widget.js';

export const Html: React.FC<PluginProps> = ({ settings: config, node, ...props }) => {
  const { patchPmNodeAttrs, pmNodeAttrs } = useNodeAttrs(node.attrs.id, 'HTML');
  const modals = useModalService();
  const [isFloatingPromptOpen, setIsFloatingPromptOpen] = useState(false);
  const iframeSandboxDomain = useEditorProp(ctx => ctx.iframeSandboxDomain);
  const getWixInstance = useWixInstanceService();
  const metaSiteId = getWixInstance().metaSiteId;

  const ricosNode = useMemo(
    () => htmlConverter.fromPm.convert(node.toJSON()) as HtmlNode,
    [node, node?.attrs?.state]
  );

  if (!pmNodeAttrs) {
    logInvariant(new Error('pmNodeAttrs is undefined'));
    return null;
  }

  const onIframeHeightChange = useCallback(
    (height: number) => {
      if (height !== pmNodeAttrs?.iframeHeight) {
        patchPmNodeAttrs?.(
          {
            ...pmNodeAttrs,
            containerData: { ...pmNodeAttrs.containerData, height: { custom: `${height}` } },
            iframeHeight: height,
          },
          { skipHistory: true }
        );
      }
    },
    [pmNodeAttrs, patchPmNodeAttrs]
  );

  useEffect(() => {
    modals.onModalOpened(modalId => {
      if (modalId === getModalId(pmNodeAttrs.id)) {
        setIsFloatingPromptOpen(true);
      }
    });

    modals.onModalClosed(modal => {
      if (modal.id === getModalId(pmNodeAttrs.id)) {
        setIsFloatingPromptOpen(false);
      }
    });
  }, [modals]);

  if (pmNodeAttrs.state === null || pmNodeAttrs.state.status === 'INITIAL') {
    return null;
  }

  if (
    (pmNodeAttrs.source === HTMLData_Source.AI ||
      pmNodeAttrs.source === HTMLData_Source.AI_WIDGET) &&
    config.enableAiMode
  ) {
    return (
      <AiWidget
        htmlNode={node}
        isFloatingPromptOpen={isFloatingPromptOpen}
        getColorPalette={config.getColorPalette}
        htmlAiGeneration={config.htmlAiGeneration}
      >
        {ricosNode && (
          <HtmlViewerWithOverlay
            {...props}
            htmlData={ricosNode?.htmlData as HTMLData}
            settings={config}
            onIframeHeightChange={onIframeHeightChange}
            disabled={isFloatingPromptOpen}
            iframeSandboxDomain={iframeSandboxDomain}
            metaSiteId={metaSiteId}
          />
        )}
      </AiWidget>
    );
  }

  return (
    <HtmlViewerWithDragAndOverlay
      {...props}
      htmlData={ricosNode?.htmlData as HTMLData}
      settings={config}
      onIframeHeightChange={onIframeHeightChange}
      iframeSandboxDomain={iframeSandboxDomain}
      metaSiteId={metaSiteId}
    />
  );
};

// These HOCs each add their own props to the component signature, so the chain
// only composes through a loosely-typed boundary (previously erased by flowRight).
const HtmlViewerAsPluginComponent =
  HtmlViewerComponent as unknown as React.ComponentType<PluginProps>;

const HtmlViewerWithDragAndOverlay = DraggableHOC(
  OverlayHoc(HtmlViewerAsPluginComponent)
) as unknown as React.ComponentType<any>;

const HtmlViewerWithOverlay = OverlayHoc(
  HtmlViewerAsPluginComponent
) as unknown as React.ComponentType<any>;
