import { definePmNodeConverter } from './../pm-converters/types.js';
import type { HTMLData } from './../ricos-schema/next-schema/index.js';
import { HTMLData_Source, Node_Type } from './../ricos-schema/next-schema/index.js';
import type { PmHtmlNode } from './../_shared/pm-node-types.js';

export const htmlConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.HTML],
    convert: node => {
      return {
        type: Node_Type.HTML,
        attrs: {
          ...node.htmlData,
          id: node.id,
          autoHeight: node.htmlData.autoHeight ?? true,
          state: {
            status: 'SUCCESS',
          },
        },
      };
    },
  },
  fromPm: {
    types: [Node_Type.HTML],
    convert: node => {
      const { id } = node.attrs || {};
      const attrs = (node.attrs || {}) as PmHtmlNode['attrs'];

      const hasContent = attrs.html !== null || attrs.widgetId !== null;
      if (
        attrs.state === null ||
        attrs.state?.status === 'INITIAL' ||
        (attrs.state?.status === 'LOADING' && !hasContent) ||
        (attrs.state?.status === 'ERROR' && !hasContent)
      ) {
        return undefined;
      }

      const htmlData: HTMLData = {
        containerData: attrs.containerData ?? undefined,
        source: attrs.source || HTMLData_Source.HTML,
        url: attrs.url || undefined,
        html: attrs.html || undefined,
        widgetId: attrs.widgetId || undefined,
        autoHeight: attrs.autoHeight === false ? false : undefined,
        ...(attrs.animation ? { animation: attrs.animation } : {}),
      };

      return {
        type: Node_Type.HTML,
        id,
        nodes: [],
        htmlData,
      };
    },
  },
});
