export const FLOATING_PROMPT_INPUT_MODAL_ID = 'FLOATING-PROMPT-INPUT';

export const FloatingPromptInput: React.FC<{
  nodeId: string;
  getColorPalette?: () => string[];
}> = ({ nodeId, getColorPalette, ...props }) => {
  const { makeRequest } = useRequestService();
  const {
    adapter: { tiptapEditor },
    getPublicCommands,
  } = React.useContext(EditorContext);
  const { t } = useContext(RicosContext);
  const ref = React.useRef<PromptInputAreaRef>(null);
  const modalService = useContext(ModalServiceContext);
  const handleFileUpload = useHandleFileUpload();

  const { patchPmNodeAttrs, pmNodeAttrs } = useNodeAttrs(nodeId, 'HTML');
  const [promptText, setPromptText] = React.useState<string>(
    pmNodeAttrs?.state?.prompt?.text ?? ''
  );

  useEffect(() => {
    if (ref.current) {
      ref.current.focus();
    }
  }, [ref.current]);

  if (!pmNodeAttrs) {
    console.error('FloatingPromptInput: pmNodeAttrs is undefined');
    return null;
  }

  const isAiWidget = pmNodeAttrs.source === HTMLData_Source.AI_WIDGET;
  const SelectedPromptInputArea = isAiWidget ? WidgetPromptInputArea : PromptInputArea;
  const handleClose = () => {
    modalService.closeModal(FLOATING_PROMPT_INPUT_MODAL_ID);

    queueMicrotask(() => {
      getPublicCommands().deleteBlock(nodeId);
    });
  };

  return (
    <FloatingContainer
      {...props}
      state="overlay"
      editorContainer={tiptapEditor.options.element as HTMLElement}
      onClickOutside={e => {
        // // Check if click is within WidgetTypeSelector content
        const popoverContent = (e.target as HTMLElement)?.closest?.(
          '[data-hook*="popover-content"]'
        );
        if (popoverContent) {
          return;
        }

        handleClose();
      }}
    >
      <SelectedPromptInputArea
        placeholder={t('HtmlPlugin_AiWidget_Input_Placeholder_Text')}
        ref={ref}
        zIndex={1000}
        maxLength={10000}
        forceMultiline
        dataHook={PROMPT_INPUT_AREA}
        value={promptText}
        onChange={text => {
          setPromptText(text);
        }}
        onClose={handleClose}
        attachments={pmNodeAttrs?.state?.prompt?.fileRefs ?? []}
        onSubmit={async () => {
          modalService.closeModal(FLOATING_PROMPT_INPUT_MODAL_ID);

          const currentRequestId = uuid();

          // Store the state before LOADING so we can restore it when setting SUCCESS
          const stateBeforeLoading = { ...pmNodeAttrs };

          tiptapEditor.commands.closeHistory();

          patchPmNodeAttrs(
            {
              state: {
                status: 'LOADING',
                requestId: currentRequestId,
                prompt: {
                  text: promptText,
                  fileRefs: pmNodeAttrs.state?.prompt?.fileRefs ?? [],
                  selectedWidgetTypeId: pmNodeAttrs?.state?.prompt?.selectedWidgetTypeId,
                },
              },
            },
            { skipHistory: true }
          );

          const colorPalette = isAiWidget ? getColorPalette?.() : undefined;

          const widgetPos = findNodeById(tiptapEditor.view.state.tr, nodeId)?.[0]?.pos;
          const documentContext =
            isAiWidget && widgetPos !== undefined
              ? tiptapEditor.state.doc.textBetween(0, widgetPos, '\n\n', '\n\n').trim() || undefined
              : undefined;

          const response = await doPrompt({
            documentContext,
            prompt: promptText,
            files: pmNodeAttrs?.state?.prompt?.fileRefs
              ?.filter(file => file.status === 'ok')
              ?.map(file => ({
                fileId: file.file.url,
                name: file.file.name,
              })),
            document: getPublicCommands().getContent() as unknown as RicosDocument,
            selection: getPublicCommands().getSelectionSlice() ?? [],
            makeRequest,
            widgetType: t(
              WIDGET_TYPE_OPTIONS.find(
                option => option.id === pmNodeAttrs?.state?.prompt?.selectedWidgetTypeId
              )?.label ?? ''
            ),
            outputMode: isAiWidget ? ('WIDGET' as OutputMode) : undefined,
            colorPalette,
          });

          const tr = tiptapEditor.view.state.tr;
          const nodeWithPos = findNodeById(tr, nodeId);
          const { node } = (nodeWithPos?.[0] ?? {}) as unknown as { node: PmHtmlNode };

          if (
            response.type === 'SUCCESS' &&
            node?.attrs?.state?.status === 'LOADING' &&
            node?.attrs?.state?.requestId === currentRequestId
          ) {
            // First restore INITIAL state (skip history), then set SUCCESS (add to history)
            // This ensures undo goes back to INITIAL, not LOADING
            patchPmNodeAttrs(
              {
                ...stateBeforeLoading,
              },
              { skipHistory: true }
            );

            if ('widgetId' in response) {
              patchPmNodeAttrs({
                widgetId: response.widgetId,
                containerData: response.containerData,
                state: { status: 'SUCCESS' },
              });
            } else if ('html' in response) {
              patchPmNodeAttrs({
                html: response.html,
                containerData: response.containerData,
                state: { status: 'SUCCESS' },
              });
            }

            const nodePos = nodeWithPos?.[0] ?? {};
            if (nodePos?.pos) {
              queueMicrotask(() => {
                tiptapEditor.commands.setNodeSelection(nodePos.pos);
              });
            }
          }

          if (
            response.type === 'ERROR' &&
            node?.attrs?.state?.status === 'LOADING' &&
            node?.attrs?.state?.requestId === currentRequestId
          ) {
            // First restore INITIAL state (skip history), then set ERROR (add to history)
            // This ensures undo goes back to INITIAL, not LOADING
            patchPmNodeAttrs(
              {
                ...stateBeforeLoading,
              },
              { skipHistory: true }
            );

            patchPmNodeAttrs({
              state: {
                status: 'ERROR',
                error: response.error,
                prompt: node?.attrs?.state?.prompt,
              },
            });
          }
        }}
        minHeight={isAiWidget ? '36px' : '170px'}
        onRemoveAttachment={id => {
          patchPmNodeAttrs({
            // @ts-expect-error
            state: {
              ...pmNodeAttrs?.state,
              prompt: {
                text: pmNodeAttrs?.state?.prompt?.text ?? '',
                fileRefs:
                  pmNodeAttrs?.state?.prompt?.fileRefs?.filter(file => file.id !== id) ?? [],
                selectedWidgetTypeId: pmNodeAttrs?.state?.prompt?.selectedWidgetTypeId,
              },
            },
          });
        }}
        fileUploadFn={async () => {
          await handleFileUpload(nodeId);
        }}
        actionBarComponent={
          isAiWidget ? undefined : (
            <>
              <WidgetTypeSelector
                options={WIDGET_TYPE_OPTIONS}
                selectedId={pmNodeAttrs?.state?.prompt?.selectedWidgetTypeId}
                onSelect={typeId => {
                  patchPmNodeAttrs({
                    state: {
                      status: 'INITIAL',
                      prompt: {
                        selectedWidgetTypeId: typeId,
                        text: pmNodeAttrs?.state?.prompt?.text ?? '',
                        fileRefs: pmNodeAttrs?.state?.prompt?.fileRefs ?? [],
                      },
                    },
                  });
                }}
                onRemove={() => {
                  patchPmNodeAttrs({
                    state: {
                      status: 'INITIAL',
                      prompt: {
                        selectedWidgetTypeId: undefined,
                        text: pmNodeAttrs?.state?.prompt?.text ?? '',
                        fileRefs: pmNodeAttrs?.state?.prompt?.fileRefs ?? [],
                      },
                    },
                  });
                }}
              />
            </>
          )
        }
        presetBarComponent={
          isAiWidget ? (
            <PresetList
              presets={PRESETS_WIDGETS_CREATE}
              onPresetSelect={preset => {
                if (pmNodeAttrs.state?.status === 'LOADING') {
                  return;
                }

                setPromptText(preset.prompt ?? '');
              }}
            />
          ) : undefined
        }
      />
    </FloatingContainer>
  );
};

