import type { ToggleButtonSkin } from '@wix/design-system';
import { Box, Button, Divider, HorizontalScroll, ToggleButton } from '@wix/design-system';
import { Sparkles } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import classes from './preset-bar-scss.js';

export type Preset = {
  id: string;
  label: string;
  icon?: React.ReactElement;
  prompt?: string;
};

export const FIX_BUTTON_PRESET: Preset = { id: 'fix', label: 'Fix', icon: <Sparkles /> };

export type PresetBarProps = {
  presets: Preset[];
  selectedPresetId?: string;
  onPresetSelect: (preset: Preset) => void;
  showFixButton?: boolean;
};

export const PresetBar: React.FC<PresetBarProps> = ({
  presets,
  selectedPresetId,
  onPresetSelect,
  showFixButton,
}) => {
  return (
    <HorizontalScroll scrollButtonSize="tiny">
      <Box className={classes.root} gap="SP1">
        {showFixButton && (
          <>
            <Button
              prefixIcon={<Sparkles />}
              onClick={() => {
                onPresetSelect(FIX_BUTTON_PRESET);
              }}
              skin="ai"
              priority="secondary"
              size="small"
            >
              Fix it
            </Button>
            <Divider direction="vertical" />
          </>
        )}
        {presets.map(preset => (
          <PresetToggle
            key={preset.id}
            preset={preset}
            selected={selectedPresetId === preset.id}
            onClick={() => onPresetSelect(preset)}
          />
        ))}
      </Box>
    </HorizontalScroll>
  );
};

export const PresetList: React.FC<Omit<PresetBarProps, 'showFixButton' | 'selectedPresetId'>> = ({
  presets,
  onPresetSelect,
}) => {
  return (
    <HorizontalScroll scrollButtonSize="tiny">
      <Box gap="SP1">
        {presets.map(preset => (
          <button
            key={preset.id}
            className={classes.presetListItem}
            onClick={() => onPresetSelect(preset)}
            type="button"
          >
            {preset.icon}
            {preset.label}
          </button>
        ))}
      </Box>
    </HorizontalScroll>
  );
};

const PresetToggle: React.FC<{
  preset: Preset;
  selected: boolean;
  onClick: () => void;
  skin?: ToggleButtonSkin;
}> = ({ preset, selected, onClick, skin }) => {
  return (
    <ToggleButton
      key={preset.id}
      selected={selected}
      onClick={onClick}
      skin={skin ?? 'standard'}
      size="small"
      labelValue={preset.label}
      shape="pill"
      border
      children={preset.icon}
    />
  );
};
