import {
  CodeObjectSmall,
  DesignSmall,
  RenameSmall,
  SparklesFilledSmall,
} from '@wix/wix-ui-icons-common/lazy';
import classNames from 'classnames';
import React from 'react';

import classes from './loader-scss.js';

export const Loader: React.FC = () => {
  return (
    <div className={classes.root}>
      <div className={classes.leftSide}>
        <Line />
        <Circle />
      </div>
      <div className={classes.scroller} data-animated="true">
        <div className={classes.scrollerInner}>
          {/* Duplicate for seamless infinite loop */}
          {[...SCROLL_ITEMS, ...SCROLL_ITEMS].map((item, index) => (
            <ScrollItem key={index} width={item.width} arrowPosition={item.arrowPosition} />
          ))}
        </div>
      </div>
    </div>
  );
};

const SCROLL_ITEMS: ScrollItemProps[] = [
  { width: '75%' },
  { width: '100%' },
  { width: '75%', arrowPosition: 'right' },
  { width: '100%' },
  { width: '75%' },
  { width: '100%', arrowPosition: 'left' },
];

type ScrollItemProps = {
  width: string;
  arrowPosition?: 'left' | 'right';
};

const ScrollItem: React.FC<ScrollItemProps> = ({ width, arrowPosition }) => {
  if (!arrowPosition) {
    return <Bar width={width} />;
  }

  return (
    <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
      {arrowPosition === 'left' && <Arrow direction="left" />}
      <Bar width={width} />
      {arrowPosition === 'right' && <Arrow direction="right" />}
    </div>
  );
};

const Bar: React.FC<{ width: React.CSSProperties['width'] }> = ({ width }) => {
  return (
    <div
      style={{
        width,
        height: '13px',
        borderRadius: '1000px',
        background: 'linear-gradient(90deg, #d6e6fe 0%, #e7f0ff 100%)',
      }}
    />
  );
};

const Arrow: React.FC<{ direction?: 'left' | 'right' } & React.SVGProps<SVGSVGElement>> = ({
  direction = 'right',
  ...props
}) => {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="7"
      height="8"
      viewBox="0 0 7 8"
      fill="none"
      style={{
        transform: direction === 'left' ? 'rotate(180deg)' : 'none',
      }}
      {...props}
    >
      <path
        d="M6.35205 2.816L5.10216e-05 0V1.456L5.23205 3.68L5.10216e-05 5.904V7.424L6.35205 4.592V2.816Z"
        fill="#116DFF"
      />
    </svg>
  );
};

const Circle: React.FC = () => {
  const [currentIndex, setCurrentIndex] = React.useState(0);

  React.useEffect(() => {
    const interval = setInterval(() => {
      setCurrentIndex(prevIndex => (prevIndex + 1) % ICONS.length);
    }, 1500);

    return () => clearInterval(interval);
  }, []);

  return (
    <div
      style={{
        width: '30px',
        height: '30px',
        borderRadius: '50%',
        background: 'linear-gradient(45deg, #A8CAFF 0%, #FFF 100%)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        position: 'relative',
      }}
    >
      {ICONS.map((Icon, index) => (
        <Icon
          key={index}
          className={classNames(classes.icon, index === currentIndex && classes.visible)}
        />
      ))}
    </div>
  );
};

const ICONS = [SparklesFilledSmall, DesignSmall, RenameSmall, CodeObjectSmall];

const Line: React.FC = () => {
  return <div className={classes.line} />;
};
