import type {
  CreateRicosConversationHTMLRequest,
  CreateRicosConversationHTMLResponse,
  RichContent,
  OutputMode,
} from '@wix/ambassador-ricos-v1-ricos-conversation/types';

import {
  type PluginContainerData,
  type RicosDocument,
  type RicosDocumentNode,
} from './../../ricos-schema/next-schema/index.js';
import type { RequestService } from './../../_shared/request-service-provider/request-service-provider.js';

type DoPromptParams = {
  prompt: string;
  files?: { fileId: string; name: string }[];
  document: RicosDocument;
  selection: RicosDocumentNode[];
  makeRequest: RequestService['makeRequest'];
  widgetType: string | undefined;
  outputMode?: OutputMode;
  colorPalette?: string[];
  documentContext?: string;
  /** Called on any failed `ricos-conversations/html` fetch; the host decides what to do per-status. */
  onRequestFailed?: (info: { status: number; response: Response }) => void;
};

type DoPromptResult =
  | { type: 'SUCCESS'; html: string; containerData: PluginContainerData | null }
  | { type: 'SUCCESS'; widgetId: string; containerData: PluginContainerData }
  | { type: 'ERROR'; error: string };

const buildPrompt = ({
  userPrompt,
  widgetType,
  isWidget,
  colorPalette,
  documentContext,
}: {
  userPrompt: string;
  widgetType: string | undefined;
  isWidget: boolean;
  colorPalette?: string[];
  documentContext?: string;
}): string => {
  const [backgroundColor, ...paletteColors] = colorPalette ?? [];
  const colorPaletteText = backgroundColor
    ? `\n\nUse ${backgroundColor} for background. Brand's color palette: ${paletteColors.join(', ')}.`
    : '';
  const placementSuffix = isWidget
    ? ', widget is placed in <WIDGET_PLACEMENT> tag. Try to use the information that is closest to the <WIDGET_PLACEMENT> tag from the <context>'
    : '';
  const widthRule = isWidget
    ? '\n\nThe widget must fill the full width of the document. Use width: 100% on the outermost container.'
    : '';
  const contextBlock =
    isWidget && documentContext?.trim()
      ? `\n\n<context>\n${documentContext}\n<WIDGET_PLACEMENT>\n</context>`
      : '';

  if (widgetType) {
    return [
      userPrompt,
      placementSuffix,
      `\n\n **IMPORTANT**\nThe type of widget to create should be of type ${widgetType}, RELEVANT to the content, its styling and request mentioned above`,
      colorPaletteText,
      widthRule,
      contextBlock,
    ].join('');
  }

  return [userPrompt, placementSuffix, colorPaletteText, widthRule, contextBlock].join('');
};

const getBaseUrl = (): string =>
  typeof location !== 'undefined' && location.hostname === 'editor.wix.com'
    ? 'https://editor.wix.com/_api/ricos-ai-assistant'
    : 'https://www.wixapis.com/ricos';

const parseResponse = (
  body: CreateRicosConversationHTMLResponse & { widgetId?: string },
  isWidget: boolean
): DoPromptResult => {
  if (isWidget) {
    const { widgetId } = body;
    if (!widgetId) {
      return { type: 'ERROR', error: 'No widgetId returned' };
    }
    return {
      type: 'SUCCESS',
      widgetId,
      containerData: {
        alignment: 'CENTER',
        textWrap: true,
        width: { custom: '900' },
        height: { custom: '474' },
      },
    };
  }

  const { html } = body;
  if (!html) {
    return { type: 'ERROR', error: 'Error generating HTML' };
  }

  return {
    type: 'SUCCESS',
    html,
    containerData: {
      alignment: 'CENTER',
      textWrap: true,
      width: { custom: body.width?.toString() ?? '900' },
      height: { custom: body.height?.toString() ?? '474' },
    },
  };
};

export const doPrompt = async ({
  prompt: userPrompt,
  files,
  document,
  selection,
  makeRequest,
  widgetType,
  outputMode,
  colorPalette,
  documentContext,
  onRequestFailed,
}: DoPromptParams): Promise<DoPromptResult> => {
  const isWidget = outputMode === 'WIDGET';
  const prompt = buildPrompt({ userPrompt, widgetType, isWidget, colorPalette, documentContext });

  try {
    const requestBody: CreateRicosConversationHTMLRequest = {
      ricosConversation: {
        document: document as RichContent,
        documentSelection: { nodes: selection } as RichContent,
        returnMetadata: true,
        files,
        message: prompt,
      },
      ...(outputMode ? { outputMode } : {}),
    };

    const response = await makeRequest(`${getBaseUrl()}/v1/ricos-conversations/html`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/x-ndjson',
      },
      body: JSON.stringify(requestBody),
    });

    const requestId = response.headers.get('x-wix-request-id');
    if (requestId) {
      // oxlint-disable-next-line no-console
      console.log(
        '\x1b[44m\x1b[97m RICOS PROMPT \x1b[0m',
        prompt,
        `https://grafana.wixpress.com/d/dewd4kmq6f400b/ricos-ai-assistant?var-selected_request_id=${requestId}`
      );
    }

    if (!response.ok) {
      onRequestFailed?.({ status: response.status, response });
      return { type: 'ERROR', error: 'Error generating response' };
    }

    const body = (await response.json()) as CreateRicosConversationHTMLResponse & {
      widgetId?: string;
    };

    return parseResponse(body, isWidget);
  } catch (error) {
    return {
      type: 'ERROR',
      error: error instanceof Error ? error.message : 'Error generating response',
    };
  }
};
