import type { htmlButtonsTypes } from './defaults.js';

export const HTML_TYPE = 'wix-draft-plugin-html';

export interface HtmlPluginEditorConfig {
  type: 'html';
  minHeight?: number;
  maxHeight?: number;
  maxWidth?: number;
  minWidth?: number;
  width?: number;
  height?: number;
  /**
   * Whether to enable AI-powered content generation and assistance features.
   * Requires authorization to use the Ricos AI conversation service.
   * When enabled, provides AI prompts and content generation capabilities within the HTML plugin.
   * Default: false
   */
  enableAiMode?: boolean;
  /**
   * When true (and `enableAiMode` is also true), uses the WixelWidgets backend
   * (`AI_WIDGET` source) instead of the Ricos AI conversation service (`AI` source).
   * Default: false
   */
  useWixelWidgets?: boolean;
  /** Host hooks for AI generation (only applied when `useWixelWidgets` is true). */
  htmlAiGeneration?: {
    /** Called before insert and each generation request; return `false` to abort. */
    canProceed?: () => Promise<boolean>;
    /** Called on any failed generation request. */
    onRequestFailed?: (info: { status: number; response: Response }) => void;
  };
  exposeButtons?: (typeof htmlButtonsTypes.html | typeof htmlButtonsTypes.adsense)[];
  siteDomain?: string;
  getColorPalette?: () => string[];
}

export interface HtmlPluginViewerConfig {
  width?: number;
  height?: number;
  siteDomain?: string;
  /** @internal @deprecated */
  getColorPalette?: () => string[];
}
